import "server-only";
import { promises as fs } from "fs";
import path from "path";
import type { Article } from "./types";
import { ALL_ARTICLES } from "@/content/articles/registry.generated";
import { isReadOnlyRuntime } from "@/lib/kv";

/**
 * Article store. Content lives in src/content/articles/*.json.
 *
 * Reads try the filesystem first (so local edits show immediately in
 * `next dev`) and fall back to a static, build-time registry when there is no
 * filesystem — i.e. on Cloudflare Workers. The registry is generated by
 * scripts/gen-content-registry.mjs (predev/prebuild hooks).
 *
 * Writes (author edits) only work where the filesystem is writable — local
 * development. On the published Worker the site is read-only: edit locally,
 * commit, redeploy.
 */

const CONTENT_DIR = path.join(process.cwd(), "src", "content", "articles");

const SLUG_RE = /^[a-z0-9-]+$/;

const REGISTRY_BY_SLUG = new Map(ALL_ARTICLES.map((a) => [a.slug, a]));

function fileFor(slug: string): string {
  if (!SLUG_RE.test(slug)) throw new Error("Invalid article slug");
  return path.join(CONTENT_DIR, `${slug}.json`);
}

export async function listArticleSlugs(): Promise<string[]> {
  try {
    const files = await fs.readdir(CONTENT_DIR);
    return files
      .filter((f) => f.endsWith(".json") && f !== "registry.generated.ts")
      .map((f) => f.replace(/\.json$/, ""));
  } catch {
    return ALL_ARTICLES.map((a) => a.slug);
  }
}

export async function getArticle(slug: string): Promise<Article | null> {
  try {
    const raw = await fs.readFile(fileFor(slug), "utf8");
    return JSON.parse(raw) as Article;
  } catch {
    return REGISTRY_BY_SLUG.get(slug) ?? null;
  }
}

export async function getAllArticles(): Promise<Article[]> {
  const slugs = await listArticleSlugs();
  const articles = await Promise.all(slugs.map((s) => getArticle(s)));
  return articles
    .filter((a): a is Article => a !== null)
    .sort((a, b) => +new Date(b.publishedAt) - +new Date(a.publishedAt));
}

/** Author-only write. Validates slug + basic shape before persisting. */
export async function saveArticle(slug: string, article: Article): Promise<void> {
  if (isReadOnlyRuntime()) {
    throw new Error(
      "Editing is only available locally (npm run dev); the published site is read-only.",
    );
  }
  if (!SLUG_RE.test(slug)) throw new Error("Invalid article slug");
  if (article.slug !== slug) throw new Error("Slug mismatch");
  if (!article.title || !Array.isArray(article.blocks)) {
    throw new Error("Malformed article");
  }
  const updated: Article = {
    ...article,
    updatedAt: new Date().toISOString().slice(0, 10),
  };
  await fs.writeFile(fileFor(slug), JSON.stringify(updated, null, 2), "utf8");
}
